window.createRapicosturaChatbotPanel=function(){
 const element=document.createElement('section');const scope=element.attachShadow({mode:'open'});scope.innerHTML="<style>:host{display:block;color:#faf6ff;font:17px/1.65 'Trebuchet MS',Arial,sans-serif}*{box-sizing:border-box}[hidden]{display:none!important}p{margin:12px 0}label{display:block;margin:17px 0 9px}small{display:block;font-size:14px;color:#cdbbd7;line-height:1.7}input,select,textarea{width:100%;font:inherit;min-height:52px;border:1px solid #ffffff33;border-radius:10px;padding:12px;color:#faf6ff;background:#20152c;color-scheme:dark}textarea{min-height:130px;resize:vertical}input:focus,textarea:focus,select:focus{outline:2px solid #bd92dc;outline-offset:2px}button{font:inherit;width:100%;min-height:52px;border:1px solid #b88bdd66;border-radius:11px;background:#bd92dc;color:#261332;padding:12px;margin:12px 0;cursor:pointer}button.light{background:#372846;color:#eadbf4}button.danger{background:#4a293d;color:#ffcfdf}button:disabled{cursor:default;opacity:.5}fieldset{border:0;min-width:0;margin:0;padding:0}fieldset:disabled{opacity:.55}fieldset:disabled button{opacity:.6}.connection{padding:20px;border:1px solid #bd92dc66;border-radius:18px;background:linear-gradient(125deg,#55316c,#342040);margin-bottom:22px}.connection h2{font-size:21px;margin:0}.connection-state{font-weight:bold;color:#e5cbf5}.setup-section{background:#2c2039;border:1px solid #ffffff22;border-radius:15px;margin:14px 0;padding:17px}.setup-section summary{font-size:18px;font-weight:bold;cursor:pointer;min-height:46px;display:flex;align-items:center;justify-content:space-between;gap:12px}.setup-section summary:after{content:'＋';color:#bd92dc}.setup-section[open] summary:after{content:'−'}h3{font-size:18px}.faq,.q{padding:15px;background:#372846;border-radius:12px;margin:14px 0}.state{white-space:pre-wrap;overflow-wrap:anywhere}.tag{font-size:12px;display:block;color:#bcdfbd}.tag.no{color:#ffd3a8}#notice{color:#eadbf4;overflow-wrap:anywhere}#notice:not(:empty){padding:15px;background:#55316c;border-radius:12px}#qr{display:block;width:100%;max-width:280px;background:white;padding:10px;border-radius:12px;margin:18px auto}code{font-size:13px;overflow-wrap:anywhere}a{color:#dfbaf6}#disconnect{margin-top:4px}#connection-message{overflow-wrap:anywhere}.local-open{display:block;background:#bd92dc;color:#261332;text-decoration:none;padding:14px;border-radius:11px;font-weight:bold;margin:16px 0}#qr-card{scroll-margin-top:12px}#qr-card #qr{margin:12px auto}#qr-card button{margin:8px 0}#qr-card p{font-size:15px}</style><section id=\"qr-card\" class=\"connection\" hidden><h2>Vincular WhatsApp</h2><p>En el celular de la dueña: WhatsApp → Dispositivos vinculados → Vincular un dispositivo.</p><fieldset disabled><button type=\"button\" class=\"light\" id=\"connect\">Mostrar QR de WhatsApp</button><p class=\"state\" id=\"wa-state\">Sin conexión</p><img id=\"qr\" hidden alt=\"Código QR para vincular WhatsApp\"></fieldset></section><section class=\"connection\"><h2>Conectar con su chatbot</h2><p id=\"connection-state\" class=\"connection-state\">Sin conectar</p><form id=\"bridge-login\"><label>Dirección del servidor<input id=\"bridge-server\" type=\"url\" placeholder=\"https://chatbot.tu-dominio.com\" required autocomplete=\"url\"></label><label>Clave de acceso al panel<input id=\"bridge-token\" type=\"password\" required autocomplete=\"off\" placeholder=\"La clave configurada en su servidor\"></label><small>Tu compañero debe publicar el servidor con la conexión para esta app. La clave se usa durante esta sesión y no se guarda en el celular.</small><button id=\"bridge-connect\">Conectar con el chatbot</button></form><button id=\"disconnect\" class=\"light\" hidden>Cerrar conexión al panel</button><p id=\"connection-message\" role=\"status\">Conecta el servidor para cargar y guardar la configuración real.</p></section><p>Configura aquí la IA, la información de la empresa y WhatsApp.</p><p id=\"notice\" role=\"status\" aria-live=\"polite\"></p>\n\n<details class=\"setup-section\"><summary>1. IA que responde 🤖</summary><fieldset disabled><small>Responde las preguntas libres (“¿cuánto pagan?”, “¿dónde quedan?”) usando solo las instrucciones y la información de la empresa (sección 2). También entiende fechas escritas. Nunca recibe el nombre, la edad ni el teléfono.</small>\n<label>IA a usar<select id=\"provider\"><option value=\"gemini\">Gemini (Google AI Studio, en la nube)</option><option value=\"ollama\">IA local (Ollama, sin internet)</option></select></label>\n<div id=\"gemini-box\"><label>Clave API de Gemini<input id=\"key\" type=\"password\" autocomplete=\"new-password\" placeholder=\"Pega aquí tu clave de Google AI Studio\"></label><small id=\"key-state\"></small><label>Modelo de Gemini<input id=\"model\" value=\"gemini-3.5-flash-lite\" required></label><small>Crea la clave gratis en aistudio.google.com → “Get API key”. Revisa la cuota gratuita del modelo.</small></div>\n<div id=\"ollama-box\"><p class=\"state\" id=\"ai-state\">Sin conectar</p><label>Modelo local<input id=\"ollama-model\" placeholder=\"qwen2.5:1.5b\" autocomplete=\"off\"></label><small>Para computadoras sencillas: <code>qwen2.5:0.5b</code>, <code>qwen2.5:1.5b</code> (recomendado) o <code>qwen2.5:3b</code>. Descárgalo con <code>ollama pull qwen2.5:1.5b</code>.</small></div>\n<br><button type=\"button\" id=\"save-ai\">Guardar</button>\n<label>Probar con una pregunta<input id=\"test-question\" value=\"¿Qué beneficios ofrecen?\"></label><button type=\"button\" class=\"light\" id=\"test-ai\">Probar IA</button><p class=\"state\" id=\"test-result\" hidden></p></fieldset></details>\n\n<details class=\"setup-section\"><summary>2. Información de la empresa 🏢</summary><fieldset disabled><small>Las instrucciones y el contexto son lo único que la IA usa para responder. Lo que no esté, lo deriva al contacto.</small>\n<label>Nombre<input id=\"nombre\"></label>\n<label>Contacto humano<input id=\"contacto\" placeholder=\"Nelly Chávez al 957 536 688\"></label>\n<label>Instrucciones para la IA<textarea id=\"instrucciones\" placeholder=\"Ejemplo: Si preguntan por sueldo, di que se conversa en la visita. No hables de otros temas que no sean el trabajo en Rapicostura. Invita siempre a agendar la visita.\"></textarea></label><small>Cómo debe responder: tono, temas que evita, a qué invita. La información (sedes, horarios, requisitos) va en el siguiente campo.</small>\n<label>Contexto de la empresa<textarea id=\"empresa\"></textarea></label>\n<h3>Preguntas frecuentes</h3><small>Se responden al instante, incluso sin IA. Las “palabras clave” ayudan a encontrar la respuesta (sinónimos, separados por espacios).</small>\n<div id=\"faqs\"></div><button type=\"button\" class=\"light\" id=\"add-faq\">+ Agregar pregunta</button><br><button type=\"button\" id=\"save-kb\">Guardar información</button></fieldset></details>\n\n<details class=\"setup-section\"><summary>3. Preguntas que hicieron 💬</summary><fieldset disabled><small>Últimas consultas libres y lo que respondió el bot. Úsalas para mejorar las preguntas frecuentes. Pueden contener datos personales: no las compartas.</small><div id=\"questions\"><p>Sin preguntas todavía.</p></div><button type=\"button\" class=\"light\" id=\"reload-q\">Actualizar</button></fieldset></details>\n\n<form id=\"config\"><details class=\"setup-section\"><summary>4. Vincular WhatsApp por QR 📱</summary><fieldset disabled><label>Números autorizados para probar el bot<input id=\"phones\" placeholder=\"51999999999, 51988888888\" autocomplete=\"off\"></label><small>Incluye código de país. El bot no responderá a nadie hasta que autorices números de prueba.</small><br><button type=\"submit\">Guardar números</button><label>Enviar un “hola” de prueba<input id=\"test-phone\" inputmode=\"tel\" placeholder=\"51987654321\" autocomplete=\"off\"></label><small>El bot le escribe primero a ese número, empieza la conversación desde el menú y lo agrega a los números autorizados. Úsalo solo con personas que aceptaron probar.</small><br><button type=\"button\" class=\"light\" id=\"greet\">Enviar hola 👋</button><p>En el celular de la cuenta de prueba abre <strong>WhatsApp → Dispositivos vinculados → Vincular un dispositivo</strong> y escanea el QR.</p><label>Velocidad de respuesta<select id=\"pace\"><option value=\"lenta\">Lenta, como una persona (recomendada)</option><option value=\"muy_lenta\">Muy lenta (más segura, tarda hasta ~50 s)</option><option value=\"normal\">Normal (más rápida, más riesgo)</option></select></label><small>El bot espera, marca como leído, muestra “escribiendo…” según el largo del mensaje y deja espacio entre envíos. También deja de responder un rato si alguien manda más de 15 mensajes en 5 minutos.</small><br><button type=\"submit\">Guardar</button>\n<p><strong>Para reducir el riesgo de bloqueo:</strong> usa un número que ya tenga uso normal (no uno recién creado), el bot solo responde a quien le escribe primero (nunca envía mensajes masivos), pide a las postulantes que te guarden como contacto y no lo conectes a muchos números a la vez.</p>\n<small>La conexión utiliza Baileys, no la API oficial de Meta: siempre existe algún riesgo. Para uso definitivo, lo más seguro es la API oficial (sección 5).</small></fieldset></details>\n<details class=\"setup-section\"><summary>5. WhatsApp oficial (API de Meta) ✅</summary><fieldset disabled><small>Si consigues acceso a la WhatsApp Cloud API, el bot responde por ahí con <strong>botones y listas reales</strong> y mediante el canal oficial. Puede funcionar junto con la conexión por QR (en otro número).</small>\n<p class=\"state\" id=\"meta-state\">Sin configurar</p>\n<label>Phone number ID<input id=\"meta-phone\" inputmode=\"numeric\" autocomplete=\"off\" placeholder=\"Ejemplo: 123456789012345\"></label>\n<label>Token de acceso (permanente, de un usuario del sistema)<input id=\"meta-token\" type=\"password\" autocomplete=\"new-password\"></label>\n<label>Clave secreta de la app (App secret)<input id=\"meta-secret\" type=\"password\" autocomplete=\"new-password\"></label>\n<button type=\"submit\">Guardar API de Meta</button>\n<p><strong>En developers.facebook.com → tu app → WhatsApp → Configuración → Webhook:</strong></p>\n<label>URL de devolución de llamada<input id=\"meta-url\" readonly></label>\n<label>Token de verificación<input id=\"meta-verify\" readonly></label>\n<small>Suscribe el campo <code>messages</code>. Meta necesita una dirección pública con HTTPS: publica el bot detrás de un proxy (Nginx/Caddy) o un túnel como Cloudflare Tunnel, y escribe aquí tu dominio en lugar de localhost.</small></fieldset></details></form>";
 const localMode=['localhost','127.0.0.1','[::1]'].includes(location.hostname)&&location.pathname.startsWith('/app/');
 let serverOrigin='',accessToken='',connected=false,active=false,localConnecting=false;const pending=new Set();
 async function remoteRequest(path,body){
  if(!connected||(!localMode&&!accessToken))throw Error('Primero conecta el servidor del chatbot.');
  const session=accessToken,controller=new AbortController();pending.add(controller);const timer=setTimeout(()=>controller.abort(),path==='test-ai'?60000:20000);
  try{const res=await fetch(serverOrigin+(localMode?'/setup/':'/app-admin/')+path,{method:body===undefined?'GET':'POST',credentials:'omit',cache:'no-store',headers:{...(localMode?{'X-Setup-Token':csrf}:{Authorization:'Bearer '+accessToken}),...(body===undefined?{}:{'Content-Type':'application/json'})},body:body===undefined?undefined:JSON.stringify(body),signal:controller.signal});
   const data=await res.json().catch(()=>({}));if(!connected||accessToken!==session)throw Error('La conexión al panel se cerró.');if(!res.ok)throw Error(data.error||'El servidor no permitió esta acción.');return data;
  }catch(error){if(error.name==='AbortError')throw Error('El servidor tardó demasiado. Vuelve a intentarlo.');if(error instanceof TypeError)throw Error('No se pudo conectar. Revisa la dirección, internet y la conexión del servidor con esta app.');throw error}finally{clearTimeout(timer);pending.delete(controller)}
 }
 
let csrf='',poll,loading=false;const $=id=>scope.getElementById(id);const notice=t=>{$('notice').textContent=t};const statusNames={idle:'Sin vincular',connecting:'Preparando el QR…',qr:'Escanea este QR con WhatsApp',connected:'WhatsApp conectado ✅',reconnecting:'Reconectando…',logged_out:'Sesión cerrada. Vuelve a generar el QR.',error:'No se pudo conectar. Intenta de nuevo.'};
async function request(path,body){return remoteRequest(path,body)}
async function refresh(initial=false){if(loading)return;loading=true;try{const s=await request('status');csrf=s.csrf;if(initial){$('model').value=s.model;$('phones').value=s.phones;$('ollama-model').value=s.ollamaModel;$('provider').value=s.provider;toggleAI();$('pace').value=s.pace;$('meta-phone').value=s.metaPhoneId}$('meta-url').value=serverOrigin+'/webhook/meta';$('meta-verify').value=s.metaVerifyToken||'(se genera al guardar)';$('meta-token').placeholder=s.metaTokenSaved?'•••••••• (token guardado)':'Pega el token de acceso';$('meta-secret').placeholder=s.metaSecretSaved?'•••••••• (clave guardada)':'Pega la clave secreta de la app';$('meta-state').textContent=s.metaPhoneId&&s.metaTokenSaved&&s.metaSecretSaved?'✅ Configurada. Falta verificar el webhook en Meta si aún no lo hiciste.':'Sin configurar';$('key-state').textContent=s.geminiConfigured?'✅ Clave guardada. No se muestra por seguridad; deja el campo vacío para conservarla.':'Todavía no hay una clave configurada.';$('key').placeholder=s.geminiConfigured?'•••••••• (clave guardada)':'Pega aquí tu clave de Google AI Studio';$('wa-state').textContent=statusNames[s.whatsapp.status]||s.whatsapp.status;if(localMode&&s.whatsapp.status==='qr')notice('Escanea el QR con el WhatsApp de la dueña.');if(localMode&&s.whatsapp.status==='connected')notice('WhatsApp vinculado. El bot responde a los números autorizados.');$('qr').hidden=!s.whatsapp.qr;if(s.whatsapp.qr)$('qr').src=s.whatsapp.qr;else $('qr').removeAttribute('src');$('connect').disabled=['connected','connecting','reconnecting'].includes(s.whatsapp.status);}catch(e){$('qr').hidden=true;$('qr').removeAttribute('src');$('wa-state').textContent='No se pudo consultar WhatsApp. Revisa que el servidor siga encendido.';$('connect').disabled=false;notice(e.message)}finally{loading=false}}
function toggleAI(){$('gemini-box').hidden=$('provider').value!=='gemini';$('ollama-box').hidden=$('provider').value!=='ollama'}$('provider').onchange=toggleAI;
async function save(){await request('settings',{apiKey:$('key').value,model:$('model').value,phones:$('phones').value,ollamaModel:$('ollama-model').value,provider:$('provider').value,pace:$('pace').value,metaPhoneId:$('meta-phone').value,metaToken:$('meta-token').value,metaAppSecret:$('meta-secret').value});$('key').value='';$('meta-token').value='';$('meta-secret').value='';await refresh();}
async function aiState(){try{const a=await request('ai');$('ai-state').textContent=!a.enabled?'IA local desactivada: el bot responde solo con las preguntas frecuentes.':!a.running?'Ollama no está abierto en esta computadora.\nInstálalo desde ollama.com y luego ejecuta: ollama pull '+a.model:a.installed?'✅ Ollama listo con '+a.model:'Ollama está abierto, pero falta descargar el modelo.\nEjecuta: ollama pull '+a.model+(a.models.length?'\nModelos instalados: '+a.models.join(', '):'')}catch(e){$('ai-state').textContent=e.message}}
// Preguntas frecuentes editables.
function faqRow(f={pregunta:'',claves:'',respuesta:''}){const box=document.createElement('div');box.className='faq';for(const [key,name,tag] of [['pregunta','Pregunta','input'],['claves','Palabras clave','input'],['respuesta','Respuesta','textarea']]){const label=document.createElement('label');label.textContent=name;const field=document.createElement(tag);field.dataset.key=key;field.value=f[key]||'';label.append(field);box.append(label)}const del=document.createElement('button');del.type='button';del.className='danger';del.textContent='Quitar';del.onclick=()=>box.remove();box.append(del);$('faqs').append(box);return box;}
async function loadKb(){const kb=await request('knowledge');$('nombre').value=kb.nombre;$('contacto').value=kb.contacto;$('instrucciones').value=kb.instrucciones||'';$('empresa').value=kb.empresa;$('faqs').replaceChildren();kb.faq.forEach(f=>faqRow(f));}
function readKb(){return {nombre:$('nombre').value,contacto:$('contacto').value,instrucciones:$('instrucciones').value,empresa:$('empresa').value,faq:[...$('faqs').children].map(box=>Object.fromEntries([...box.querySelectorAll('[data-key]')].map(f=>[f.dataset.key,f.value])))};}
async function loadQuestions(){const list=await request('questions');const box=$('questions');box.replaceChildren();if(!list.length){const p=document.createElement('p');p.textContent='Sin preguntas todavía.';box.append(p);return}for(const q of list){const row=document.createElement('div');row.className='q';const ask=document.createElement('p');const strong=document.createElement('strong');strong.textContent=q.text;const tag=document.createElement('span');tag.className='tag'+(q.known?'':' no');tag.textContent=(q.known?'respondida':'sin respuesta')+' · '+q.source+' · '+q.channel;ask.append(strong,' ',tag);const answer=document.createElement('p');answer.textContent='↳ '+q.answer;const add=document.createElement('button');add.type='button';add.className='light';add.textContent='Convertir en pregunta frecuente';add.onclick=()=>{const r=faqRow({pregunta:q.text,claves:'',respuesta:q.known?q.answer:''});r.scrollIntoView({behavior:'smooth'});r.querySelector('textarea').focus();notice('Revisa la respuesta y pulsa “Guardar información”.')};row.append(ask,answer,add);box.append(row)}}
$('greet').onclick=async()=>{const b=$('greet');b.disabled=true;notice('Enviando el saludo… (el bot escribe a ritmo de persona)');try{const r=await request('greet',{phone:$('test-phone').value});$('phones').value=r.phones;notice('Saludo enviado ✅ Cuando esa persona responda, el bot seguirá la conversación.')}catch(e){notice(e.message)}finally{b.disabled=false}};
$('add-faq').onclick=()=>faqRow().querySelector('input').focus();
$('save-kb').onclick=async()=>{try{await request('knowledge',readKb());notice('Información de la empresa guardada ✅ El bot ya la usa.')}catch(e){notice(e.message)}};
$('reload-q').onclick=()=>loadQuestions().catch(e=>notice(e.message));
$('save-ai').onclick=async()=>{try{await save();await aiState();notice('Configuración de IA guardada ✅')}catch(e){notice(e.message)}};
$('test-ai').onclick=async()=>{const out=$('test-result');try{$('test-ai').disabled=true;out.hidden=false;out.textContent='Pensando…';const r=await request('test-ai',{question:$('test-question').value});out.textContent=r.answer+'\n\n'+(r.known?'✅':'⚠️ No encontró la respuesta en la información de la empresa.')+' · '+r.seconds+' s'}catch(e){out.textContent=e.message}finally{$('test-ai').disabled=false}};
$('config').onsubmit=async e=>{e.preventDefault();try{await save();notice('Configuración guardada ✅')}catch(e){notice(e.message)}};
$('connect').onclick=async()=>{try{$('connect').disabled=true;const current=await request('status');if(current.whatsapp.status!=='qr'&&current.whatsapp.status!=='connected')await request('connect',{});await refresh();$('qr-card').scrollIntoView({block:'start',behavior:'smooth'});}catch(e){notice(e.message)}finally{await refresh()}};


 scope.querySelector('.connection:not(#qr-card)').insertAdjacentHTML('afterbegin',"<div id=\"local-entry\"><p><strong>Esta web aún no tiene un servidor conectado.</strong></p><p>Si el bot está encendido en esta computadora, abre su panel para ver el QR.</p><a class=\"local-open\" href=\"http://127.0.0.1:8091/app/?vista=duena&amp;seccion=chatbot\">Abrir bot de esta computadora ↗</a><small>Este acceso local no funciona desde otro celular. Para usar la APK se necesita publicar el servidor.</small></div>");
 const loginForm=$('bridge-login'),serverField=$('bridge-server'),tokenField=$('bridge-token'),message=$('connection-message');
 $('local-entry').hidden=localMode;const remoteOptions=document.createElement('details');remoteOptions.innerHTML='<summary>Conectar un servidor HTTPS</summary>';loginForm.before(remoteOptions);remoteOptions.append(loginForm);if(localMode)remoteOptions.hidden=true;scope.querySelectorAll('.setup-section').forEach(section=>section.hidden=true);
 try{serverField.value=localStorage.getItem('rapicostura-chatbot-server')||''}catch{}
 function enableFields(enabled){$('qr-card').hidden=!enabled;scope.querySelectorAll('.setup-section').forEach(section=>section.hidden=!enabled);if(enabled)$('local-entry').hidden=true;scope.querySelectorAll('.setup-section fieldset,#qr-card fieldset').forEach(f=>f.disabled=!enabled)}
 function stopPoll(){clearInterval(poll);poll=null}
 function startPoll(){stopPoll();if(active&&connected)poll=setInterval(()=>{if(!document.hidden)refresh()},localMode?2000:10000)}
 function disconnect(){stopPoll();loading=false;connected=false;accessToken='';for(const c of pending)c.abort();pending.clear();enableFields(false);loginForm.hidden=false;$('disconnect').hidden=true;$('connection-state').textContent='Sin conectar';$('local-entry').hidden=localMode;scope.querySelector('.connection:not(#qr-card)').hidden=false;tokenField.value='';$('qr').hidden=true;$('qr').removeAttribute('src');$('notice').textContent='';$('wa-state').textContent='Sin conectar';$('meta-state').textContent='Sin conectar';$('ai-state').textContent='Sin conectar';scope.querySelectorAll('input,textarea').forEach(i=>{if(i!==serverField)i.value=''});$('faqs').replaceChildren();$('questions').replaceChildren();$('test-result').textContent='';}
 loginForm.onsubmit=async event=>{
  event.preventDefault();const button=$('bridge-connect');let parsed;try{parsed=new URL(serverField.value.trim());if(parsed.protocol!=='https:'||parsed.username||parsed.password||parsed.search||parsed.hash||parsed.pathname!=='/')throw Error();}catch{message.textContent='Escribe solo la dirección HTTPS del servidor, por ejemplo https://chatbot.tu-dominio.com';return}
  accessToken=tokenField.value.trim();if(!accessToken){message.textContent='Ingresa la clave de acceso.';return}serverOrigin=parsed.origin;connected=true;button.disabled=true;message.textContent='Conectando…';
  try{await request('status');await Promise.all([refresh(true),loadKb(),loadQuestions()]);enableFields(true);loginForm.hidden=true;$('disconnect').hidden=false;$('connection-state').textContent='Panel conectado';message.textContent='Los cambios que guardes se aplicarán al servidor del chatbot.';tokenField.value='';try{localStorage.setItem('rapicostura-chatbot-server',serverOrigin)}catch{}startPoll();aiState();}
  catch(error){disconnect();message.textContent=error.message}finally{button.disabled=false}
 };
 async function connectLocal(){
  if(localConnecting)return;localConnecting=true;serverOrigin=location.origin;connected=true;loginForm.hidden=true;message.textContent='Conectando con el bot de esta computadora…';
  try{const status=await request('status');csrf=status.csrf;await Promise.all([refresh(true),loadKb(),loadQuestions()]);enableFields(true);$('connection-state').textContent='Servidor local conectado';$('disconnect').hidden=false;$('disconnect').textContent='Cerrar acceso al panel';message.textContent='Para vincular el 957 536 688, abre WhatsApp en ese celular → Dispositivos vinculados → Vincular un dispositivo y escanea el QR de abajo.';scope.querySelector('.connection:not(#qr-card)').hidden=true;const meta=$('meta-phone').closest('details');meta.hidden=true;startPoll();}
  catch(error){disconnect();message.textContent=error.message}finally{localConnecting=false}
 }
 $('disconnect').onclick=()=>{disconnect();scope.querySelectorAll('input,textarea').forEach(i=>{if(i!==serverField)i.value=''});$('faqs').replaceChildren();$('questions').replaceChildren();message.textContent='Conexión cerrada. Vuelve a ingresar la clave para acceder.';};
 return {element,resume(){active=true;if(localMode&&!connected)connectLocal();else startPoll()},pause(){active=false;stopPoll()},lock(){active=false;disconnect();scope.querySelectorAll('input,textarea').forEach(i=>{if(i!==serverField)i.value=''});$('faqs').replaceChildren();$('questions').replaceChildren();$('test-result').textContent='';message.textContent='Conecta el servidor para cargar y guardar la configuración real.';}};
};
